"""C++ emitters of the parameter schema: structs (user units and SI), layout checks, descriptor tables, defaults."""
from __future__ import annotations

import hashlib
import json
import re
from dataclasses import asdict

from schema_model import LIST_KIND, Flat, Leaf, Model, Unit, camel

BANNER = """// <auto-generated>
// Generated by schema/tools/generate_params.py from {sources}. DO NOT EDIT.
// Regenerate with: python schema/tools/generate_params.py generate
// schema fingerprint: {fingerprint}
// </auto-generated>
"""


def cpp_str(text: str) -> str:
    return json.dumps(text)


def cpp_real(x) -> str:
    x = float(x)
    if x == float("inf"):
        return "kUnbounded"
    if x == float("-inf"):
        return "-kUnbounded"
    text = repr(x)
    return text if any(c in text for c in ".en") else text + ".0"


def fingerprint(models: list[Model], units: dict[str, Unit]) -> str:
    """Hash of everything the generated files depend on (comments in the YAML files do not count)."""
    payload = [[m.path.name, m.struct_order, m.documents, m.unity_only,
                [(f.path, f.xml_path, f.offset, f.document, asdict(f.leaf)) for f in m.flat]] for m in models]
    payload.append({k: asdict(v) for k, v in sorted(units.items())})
    return hashlib.sha256(json.dumps(payload, sort_keys=True, default=str).encode()).hexdigest()[:16]


# --------------------------------------------------------------------------------------------------------------------
# structs
# --------------------------------------------------------------------------------------------------------------------
def member_line(c, family: str, units: dict[str, Unit]) -> str:
    if isinstance(c, Leaf):
        unit = ""
        if c.unit and c.type not in ("bool", "enum"):
            unit = f"[{units[c.unit].si if family == 'si' else c.unit}] "
        return f"    {c.kind['cpp'] + ' ' + c.name + ';':<46}// {unit}{c.doc}" + (" (calculated)" if c.calculated else "")
    return f"    {c.struct} {c.name}" + (f"[{c.array_count}];" if c.array_count else ";")


def emit_struct(model: Model, name: str, family: str, units: dict[str, Unit]) -> str:
    lines = [f"struct {name} {{"]
    lines += [member_line(c, family, units) for c in model.structs[name].children]
    lines.append("};")
    return "\n".join(lines)


# --------------------------------------------------------------------------------------------------------------------
# source pieces
# --------------------------------------------------------------------------------------------------------------------
def chain_expr(f: Flat, qualifier: str) -> str:
    parts = []
    for struct, member, index, stride in f.chain:
        parts.append(f"offsetof({qualifier}{struct}, {member})")
        if index is not None:
            parts.append(f"{index} * {stride}")
    return " + ".join(parts)


def default_assignments(model: Model, root: str) -> list[str]:
    out = []
    for f in model.flat:
        if f.root != root or f.leaf.calculated:
            continue
        leaf, target, d = f.leaf, "p." + f.path.replace("/", "."), f.leaf.default
        if leaf.type == "real":
            out.append(f"    {target} = {cpp_real(d)};")
        elif leaf.type in ("int", "enum"):
            out.append(f"    {target} = {int(d)};")
        elif leaf.type == "bool":
            out.append(f"    {target} = {'true' if d else 'false'};")
        elif leaf.type in ("vec3", "bank3"):
            ctype = "math::Vec3" if leaf.type == "vec3" else "Bank3"
            out.append(f"    {target} = {ctype}{{{{{', '.join(cpp_real(x) for x in d)}}}}};")
        elif leaf.type == "mat3":
            m = [1, 0, 0, 0, 1, 0, 0, 0, 1] if d == "identity" else d
            rows = ", ".join("{" + ", ".join(cpp_real(m[3 * r + c]) for c in range(3)) + "}" for r in range(3))
            out.append(f"    {target} = math::Mat3{{{{{rows}}}}};")
        elif leaf.type == LIST_KIND:
            out.append(f"    {target}.count = {len(d)};")
            for i, e in enumerate(d):
                out.append(f"    {target}.items[{i}] = math::Vec3{{{{{', '.join(cpp_real(x) for x in e)}}}}};")
    return out


def descriptor_rows(model: Model, units: dict[str, Unit], root: str) -> tuple[list[str], list[str]]:
    options, rows = [], []
    for f in model.flat:
        if f.root != root:
            continue
        leaf = f.leaf
        if leaf.type == "enum":
            lo, hi = 0, len(leaf.options) - 1
        elif leaf.type == "bool":
            lo, hi = 0, 1
        else:
            lo, hi = leaf.min, leaf.max
        unit = units[leaf.unit] if leaf.unit else None
        opt = "nullptr"
        if leaf.type == "enum":
            opt = "kOptions_" + re.sub(r"\W", "_", f.path)
            options.append(f"constexpr std::string_view {opt}[] = {{{', '.join(cpp_str(o) for o in leaf.options)}}};")
        fields = [
            cpp_str(f.path), cpp_str(f.xml_path), cpp_str(leaf.unit or ""), cpp_str(leaf.doc),
            f"ParamType::{leaf.kind['ptype']}", f"ParamDocument::{camel(f.document)}",
            "true" if leaf.calculated else "false", "true" if leaf.required else "false",
            str(f.offset), str(leaf.max_count if leaf.type == LIST_KIND else 1),
            cpp_real(lo) if lo is not None else "-kUnbounded", cpp_real(hi) if hi is not None else "kUnbounded",
            cpp_real(unit.factor if unit else 1.0), cpp_real(unit.offset if unit else 0.0), opt, str(len(leaf.options))]
        rows.append("    {" + ", ".join(fields) + "},")
    return options, rows


# --------------------------------------------------------------------------------------------------------------------
# documents (shared by all schema files)
# --------------------------------------------------------------------------------------------------------------------
def emit_documents(models: list[Model], fp: str) -> tuple[str, str]:
    docs = []
    for m in models:
        for name, info in m.documents.items():
            docs.append((name, info["root_element"], info["encoding"] == "plain", list(m.unity_only.get(name, []) or [])))
    banner = BANNER.format(sources=", ".join(m.path.name for m in models), fingerprint=fp)
    enum_values = ", ".join(camel(d[0]) for d in docs)
    hpp = banner + f"""#pragma once

#include <cstddef>
#include <cstdint>
#include <span>
#include <string_view>

namespace hoverhere::params {{

enum class ParamDocument : std::uint8_t {{ {enum_values} }};

// Layout of one kind of XML file the parameters are read from.
struct DocumentInfo {{
    ParamDocument id;
    std::string_view name;                               // key in the schema
    std::string_view root_element;                       // root element of the file
    bool plain_encoding;                                 // false: <name><val>..</val></name>, true: <name>..</name> (geometry files)
    std::span<const std::string_view> ignored_elements;  // element paths (prefix or glob) that are no physics parameters
}};

[[nodiscard]] const DocumentInfo& document_info(ParamDocument id) noexcept;

inline constexpr std::string_view kSchemaFingerprint = "{fp}";

}}  // namespace hoverhere::params
"""
    body, rows = [], []
    for name, root, plain, patterns in docs:
        if patterns:
            items = ",\n    ".join(cpp_str(p) for p in patterns)
            body.append(f"constexpr std::string_view kIgnored_{name}[] = {{\n    {items}}};\n")
            span = f"kIgnored_{name}"
        else:
            span = "{}"
        rows.append(f"    {{ParamDocument::{camel(name)}, {cpp_str(name)}, {cpp_str(root)}, {'true' if plain else 'false'}, {span}}},")
    nl = "\n"
    cpp = banner + f"""#include "hoverhere/params/param_documents.hpp"

namespace hoverhere::params {{
namespace {{

{nl.join(body)}const DocumentInfo kDocuments[] = {{
{nl.join(rows)}
}};

}}  // namespace

const DocumentInfo& document_info(const ParamDocument id) noexcept
{{
    return kDocuments[static_cast<std::size_t>(id)];
}}

}}  // namespace hoverhere::params
"""
    return hpp, cpp


# --------------------------------------------------------------------------------------------------------------------
# one schema file
# --------------------------------------------------------------------------------------------------------------------
def emit_model(model: Model, units: dict[str, Unit], fp: str, header: str, namespace: str, si_family: bool,
               descriptors_fn: dict[str, str], default_fn: dict[str, str]) -> tuple[str, str]:
    banner = BANNER.format(sources=model.path.name, fingerprint=fp)
    families = [("user", "user::", "units as in the parameter files (deg, rpm, ...)")]
    if si_family:
        families.append(("si", "si::", "SI units (rad, rad/s, ...), produced by to_si()"))
    else:
        families = [("user", "", "")]

    h = [banner + "#pragma once\n", "#include <cstdint>", "#include <span>", "", '#include "hoverhere/core/math.hpp"',
         '#include "hoverhere/params/param_types.hpp"', "", f"namespace {namespace} {{", ""]
    for family, qualifier, note in families:
        if qualifier:
            h += [f"namespace {family} {{  // {note}", ""]
        for name in model.struct_order:
            h += [emit_struct(model, name, family, units), ""]
        if qualifier:
            h += [f"}}  // namespace {family}", ""]
    for root in model.roots:
        if si_family:
            h += [f"using {root.struct} = user::{root.struct};", f"using {root.struct}SI = si::{root.struct};"]
    h.append("")
    for root in model.roots:
        h += [f"// All parameters of {root.struct} with their documented default values.",
              f"[[nodiscard]] {root.struct} {default_fn[root.struct]}() noexcept;", ""]
    for root in model.roots:
        h += [f"// Descriptor of every leaf of {root.struct} (see ParamDescriptor).",
              f"[[nodiscard]] std::span<const ParamDescriptor> {descriptors_fn[root.struct]}() noexcept;", ""]
    h.append(f"}}  // namespace {namespace}")

    q0 = families[0][1]
    s = [banner + f'#include "hoverhere/params/{header}"', "", "#include <cstddef>", "", f"namespace {namespace} {{", "namespace {", "",
         "static_assert(sizeof(bool) == 1 && sizeof(std::int32_t) == 4 && sizeof(Real) == 8 && alignof(Real) == 8);",
         "static_assert(sizeof(Bank3) == 24 && sizeof(math::Vec3) == 24 && sizeof(math::Mat3) == 72);"]
    for cap in sorted({f.leaf.max_count for f in model.flat if f.leaf.type == LIST_KIND}):
        s.append(f"static_assert(sizeof(Vec3List<{cap}>) == {8 + 24 * cap} && alignof(Vec3List<{cap}>) == 8);")
    s.append("")
    for name in model.struct_order:
        size, align = model.struct_info[name]
        s.append(f"static_assert(sizeof({q0}{name}) == {size} && alignof({q0}{name}) == {align});")
        s += [f"static_assert(offsetof({q0}{name}, {c.name}) == {c.offset});" for c in model.structs[name].children]
        if si_family:
            s.append(f"static_assert(sizeof(si::{name}) == sizeof(user::{name}));")
    s.append("")
    s += [f"static_assert({chain_expr(f, q0)} == {f.offset});" for f in model.flat]
    s.append("")
    for root in model.roots:
        options, rows = descriptor_rows(model, units, root.struct)
        s += options + ([""] if options else [])
        s += [f"constexpr ParamDescriptor k{root.struct}Descriptors[] = {{"] + rows + ["};", ""]
    s += ["}  // namespace", ""]
    for root in model.roots:
        s += [f"std::span<const ParamDescriptor> {descriptors_fn[root.struct]}() noexcept", "{",
              f"    return k{root.struct}Descriptors;", "}", ""]
    for root in model.roots:
        s += [f"{root.struct} {default_fn[root.struct]}() noexcept", "{", f"    {root.struct} p{{}};"]
        s += default_assignments(model, root.struct)
        s += ["    return p;", "}", ""]
    s.append(f"}}  // namespace {namespace}")
    return "\n".join(h) + "\n", "\n".join(s) + "\n"
